"""Tests for web/public/datos/intervencions_light.json (generated by export_dataset.py).

The light JSON strips text_cas/text_val to reduce payload (~80% smaller than
the full public JSON) while keeping all fields needed for listing and filtering.
"""

import json
from pathlib import Path

import pytest

ROOT = Path(__file__).parent.parent.parent
LIGHT_JSON = ROOT / "web" / "public" / "datos" / "intervencions_light.json"
FULL_JSON = ROOT / "data" / "intervencions.json"

REQUIRED_FIELDS = {
    "id", "pleno_id", "fecha", "mandat_id",
    "intervinient", "entitat", "entitat_id", "tipus_entitat",
    "idioma_original", "ambit", "zones", "districtes",
    "temes", "temes_v2",
    "resum_cas", "resum_val",
}

TEXT_FIELDS = {"text_cas", "text_val"}


@pytest.fixture(scope="module")
def light():
    if not LIGHT_JSON.exists():
        pytest.skip(f"Light JSON not found: {LIGHT_JSON}. Run export_dataset.py first.")
    return json.loads(LIGHT_JSON.read_text())


@pytest.fixture(scope="module")
def full_count():
    if not FULL_JSON.exists():
        pytest.skip("intervencions.json not found.")
    return len(json.loads(FULL_JSON.read_text()))


def test_light_json_exists():
    assert LIGHT_JSON.exists(), (
        f"{LIGHT_JSON} missing — run: python3 scripts/export_dataset.py"
    )


def test_light_json_count_matches_full(light, full_count):
    assert len(light) == full_count, (
        f"Light JSON has {len(light)} records but full JSON has {full_count}"
    )


def test_light_json_no_text_fields(light):
    with_text = [iv["id"] for iv in light if any(f in iv for f in TEXT_FIELDS)]
    assert with_text == [], (
        f"{len(with_text)} records still contain text_cas/text_val: {with_text[:3]}"
    )


def test_light_json_required_fields_present(light):
    missing = [
        iv["id"]
        for iv in light
        if not REQUIRED_FIELDS.issubset(iv.keys())
    ]
    assert missing == [], (
        f"{len(missing)} records missing required fields: {missing[:3]}"
    )


def test_light_json_resum_not_empty(light):
    empty = [
        iv["id"] for iv in light
        if not iv.get("resum_cas") and not iv.get("resum_val")
    ]
    # Allow a small number of genuinely empty resumenes
    assert len(empty) <= 5, (
        f"{len(empty)} records have neither resum_cas nor resum_val: {empty[:5]}"
    )


def test_light_json_size_reduction():
    if not LIGHT_JSON.exists() or not FULL_JSON.exists():
        pytest.skip("Files not found.")
    light_kb = LIGHT_JSON.stat().st_size / 1024
    full_kb = FULL_JSON.stat().st_size / 1024
    ratio = light_kb / full_kb
    assert ratio < 0.5, (
        f"Light JSON ({light_kb:.0f} KB) is not significantly smaller than "
        f"full JSON ({full_kb:.0f} KB) — ratio={ratio:.2f}"
    )
